#include <iostream>

// Mô phỏng cấu trúc 2 tệp trong một đơn vị biên dịch duy nhất:
// Phần định nghĩa biến toàn cục (như trong translation unit A)
int global_counter = 42;

// Khai báo nguyên mẫu hàm (như trong tệp tiêu đề)
void display_counter();

// Định nghĩa hàm sử dụng khai báo extern (như trong translation unit B)
void display_counter() {
    extern int global_counter; // Khai báo extern cục bộ tham chiếu tới biến toàn cục
    std::cout << "Counter: " << global_counter << "\n";
}

int main() {
    display_counter();
    global_counter = 100;
    display_counter();
    return 0;
}

#include <iostream>

// Macro sai: thiếu dấu ngoặc
#define BAD_SQUARE(x) (x * x)

// Macro đúng quy tắc ngoặc nhưng vẫn dính lỗi side-effects
#define SAFE_MACRO_SQUARE(x) ((x) * (x))

// Giải pháp C++ hiện đại an toàn kiểu và không có tác dụng phụ lặp
template <typename T>
constexpr T modern_square(T x) {
    return x * x;
}

int main() {
    int a = 2;
    int b = 3;

    // Cạm bẫy độ ưu tiên toán tử:
    std::cout << "BAD_SQUARE(2 + 3): " << BAD_SQUARE(a + b) << "\n";
    std::cout << "SAFE_MACRO_SQUARE(2 + 3): " << SAFE_MACRO_SQUARE(a + b) << "\n";
    std::cout << "modern_square(2 + 3): " << modern_square(a + b) << "\n";

    return 0;
}

#include <iostream>

// Định nghĩa cờ tiền xử lý cấu hình tính năng
#define CONFIG_LEVEL 2
#define ENABLE_LOGGING

// Mô phỏng cấu trúc include guard bên trong cùng 1 file
#ifndef MATH_UTILS_H
#define MATH_UTILS_H

int custom_max(int a, int b) {
    return (a > b) ? a : b;
}

#endif // MATH_UTILS_H

// Mô phỏng việc include lặp lại lần 2 (khối này sẽ an toàn được bỏ qua)
#ifndef MATH_UTILS_H
#define MATH_UTILS_H
int custom_max(int a, int b); // Không bao giờ chạm tới đây
#endif

int main() {
#if CONFIG_LEVEL > 1
    std::cout << "High performance mode active.\n";
#else
    std::cout << "Standard mode active.\n";
#endif

#ifdef ENABLE_LOGGING
    std::cout << "Log: calculating max(15, 27)\n";
#endif

    std::cout << "Max value: " << custom_max(15, 27) << "\n";
    return 0;
}
